# ASANFinance/AsanDmInpl.dfm:7 BankInfo (TOracleDataSet)
SQL_ASAN_BANKINFO = 'select BANK,logo,az_name ,fond_reg_no from bankinfo_t where kod_fil=0'

# ASANFinance/AsanDmInpl.dfm:45 OracleQuery1 (TOracleQuery)
SQL_ASAN_ORACLEQUERY1 = 'begin\n  asan_transaction.cek_asan(\n    :fin ,\n    :service,\n    :status,\n    :js\n    );\nend;'

# ASANFinance/AsanDmInpl.dfm:65 LogDSest (TOracleDataSet)
SQL_ASAN_LOGDSEST = "select info from asan_log a where a.status='success' and service=:service and pin=:pin \n\nand  nvl(docnumber,'XX')= nvl(:doc,'XX') \nand trunc(dat)>=trunc(sysdate)-3\norder by id desc"

# ASANFinance/AsanDmInpl.dfm:84 InsAsanLog (TOracleDataSet)
SQL_ASAN_INSASANLOG = "select rowid,a.* from asan_log a where pin='11111'"

# ASANFinance/AsanDmInpl.dfm:131 IdDSet (TOracleDataSet)
SQL_ASAN_IDDSET = 'select \nseq_asan_loq.NEXTVAL id from dual'

# ASANFinance/AsanDmInpl.dfm:144 EmployerDataSet (TOracleDataSet)
SQL_ASAN_EMPLOYERDATASET = "select s.id,a.*,nvl(a.EndDate,a.PeriodType)mqavile_bitme from asan_log s,JSON_TABLE(info, '$.Response.Active[*]' COLUMNS (\n                         row_number FOR ORDINALITY  ,\n                          Voen VARCHAR2(20) PATH '$.Employer.Voen',\n                          Name VARCHAR2(100) PATH '$.Employer.Name',\n                          WorkerCount VARCHAR2(8) PATH '$.Employer.WorkerCount',\n                          LegalAddress VARCHAR2(150) PATH '$.Employer.LegalAddress',\n                          Firm_Phone VARCHAR2(150) PATH '$.Employer.Phone',\n                          EmlakNovu VARCHAR2(150) PATH '$.Employer.PropertyType.Description',\n                         \n                          IshciAdi VARCHAR2(80) PATH '$.Employee.Name',\n                          Surname VARCHAR2(80) PATH '$.Employee.Surname',\n                          Patronymic VARCHAR2(90) PATH '$.Employee.Patronymic',\n                          Phone  VARCHAR2(5) PATH '$.Employee.Phone',\n                          IshyeriNovu VARCHAR2(15) PATH '$.Employee.WorkPlaceType.Description' ,\n                          WorkPlace VARCHAR2(200) PATH '$.Employee.WorkPlace',  \n                          Position VARCHAR2(120) PATH '$.Employee.Position' , \n                          PositionLabourContract VARCHAR2(90) PATH '$.Employee.PositionLabourContract' ,\n                          Salary  VARCHAR2(15) PATH '$.Employee.Salary',\n                          WorkCasualType VARCHAR2(20) PATH '$.Employee.WorkCasualType.Description' ,\n                          SSN VARCHAR2(20) PATH '$.Employee.SSN' , \n                          BeginDate VARCHAR2(20) PATH '$.Contract.BeginDate',\n                          EndDate VARCHAR2(20) PATH '$.Contract.EndDate',\n                          NextEndDate  VARCHAR2(20) PATH '$.Contract.NextEndDate',\n                          PeriodType VARCHAR2(20) PATH '$.Contract.PeriodType.Description' ,\n                          Nomre VARCHAR2(20) PATH '$.Contract.Number'            \n                          )\n                          )a\n\n\nwhere id=:id"

# ASANFinance/AsanDmInpl.dfm:346 Status (TOracleDataSet)
SQL_ASAN_STATUS = "select s.id,a.* from asan_log s,JSON_TABLE(info, '$.Status[*]' COLUMNS (\n                          Code VARCHAR2(20) PATH '$.Code',\n                          Message VARCHAR2(200) PATH '$.Message'\n                          )\n                          )a\n\n\nwhere id=:id\n"

# ASANFinance/AsanDmInpl.dfm:379 DeActiveEmpDSet (TOracleDataSet)
SQL_ASAN_DEACTIVEEMPDSET = "select s.id,a.* from asan_log s,JSON_TABLE(info, '$.Response.Deactive[*]' COLUMNS (\n                         row_number FOR ORDINALITY  ,\n                          Voen VARCHAR2(20) PATH '$.Employer.Voen',\n                          Name VARCHAR2(100) PATH '$.Employer.Name',\n                          Position VARCHAR2(100) PATH '$.Employee.Position',\n                          Salary VARCHAR2(20) PATH '$.Employee.Salary',\n                          BeginDate VARCHAR2(100) PATH '$.Contract.BeginDate',\n                          EndDate VARCHAR2(20) PATH '$.Contract.EndDate'\n                         \n                          )\n                          )a\n\nwhere id=:id"

# ASANFinance/AsanDmInpl.dfm:454 PensionDSet (TOracleDataSet)
SQL_ASAN_PENSIONDSET = "select s.id,a.* from asan_log s,JSON_TABLE(info, '$.Response[*]' COLUMNS (\n                          Name VARCHAR2(20) PATH '$.Name',\n                          Surname VARCHAR2(20) PATH '$.Surname' ,\n                          Patronymic VARCHAR2(20) PATH '$.Patronymic' ,\n                          BirthDate VARCHAR2(20) PATH '$.BirthDate',\n                          AllBeginDate VARCHAR2(20) PATH '$.Allowance.BeginDate',\n                          AllEndDate VARCHAR2(20) PATH '$.Allowance.EndDate',\n                          AllType VARCHAR2(400) PATH '$.Allowance.Type.Description' ,\n                          AllGroup VARCHAR2(400) PATH '$.Allowance.Group.Description',\n                          AllAmount VARCHAR2(20) PATH '$.Allowance.Amount',\n                          \n                          PenLabel VARCHAR2(200) PATH '$.Pension.Type.Label',\n                          PenDescription VARCHAR2(200) PATH '$.Pension.Type.Description',\n                          PenStartDate VARCHAR2(20) PATH '$.Pension.StartDate',\n                          PenEndDate VARCHAR2(20) PATH '$.Pension.EndDate', \n                          PenAmount VARCHAR2(20) PATH '$.Pension.Amount'    \n                          )\n                          )a\nwhere id=:id"

# ASANFinance/AsanDmInpl.dfm:580 FarmPersonDset (TOracleDataSet)
SQL_ASAN_FARMPERSONDSET = "select s.id,a.* from asan_log s,JSON_TABLE(info, '$.Response.Person[*]' COLUMNS (\n                          Pin VARCHAR2(20) PATH '$.Pin',\n                          FirstName VARCHAR2(100) PATH '$.FirstName',\n                          LastName VARCHAR2(100) PATH '$.LastName',\n                          FatherName VARCHAR2(100) PATH '$.FatherName',\n                          BirthDate VARCHAR2(100) PATH '$.BirthDate'\n                          )\n                          )a\n\n\nwhere id=:id"

# ASANFinance/AsanDmInpl.dfm:643 FarmSet (TOracleDataSet)
SQL_ASAN_FARMSET = "select s.id,a.* from asan_log s,JSON_TABLE(info, '$.Response[*]' COLUMNS (\n                          fId VARCHAR2(20) PATH '$.Farms.Id',\n                          Name VARCHAR2(100) PATH '$.Farms.Name',\n                           NESTED PATH '$.Farms.Fields[*]'\n                           COLUMNS(  Fields FOR ORDINALITY  ,\n                                   VillageName VARCHAR2(30) PATH '$.VillageName',\n                                   DocType VARCHAR2(30) PATH '$.DocType',\n                                   FieldAmount VARCHAR2(30) PATH '$.FieldAmount',\n                                   Unit VARCHAR2(30) PATH '$.Unit'\n                                  ,\n                           NESTED PATH '$.Plants[*]'\n                           COLUMNS(  Plants FOR ORDINALITY  ,\n                                   PlName VARCHAR2(300) PATH '$.Name',\n                                   PlFieldAmount VARCHAR2(10) PATH '$.FieldAmount',\n                                   PlUnit VARCHAR2(6) PATH '$.Unit'\n                                  )        \n                          \n                          )))a\n\n\nwhere s.id=:id"

# ASANFinance/AsanDmInpl.dfm:750 XercSet (TOracleDataSet)
SQL_ASAN_XERCSET = "select s.id,a.* from asan_log s,JSON_TABLE(info, '$.Response.Expenses[*]' COLUMNS (\n                          row_number FOR ORDINALITY  ,\n                          Pin VARCHAR2(20) PATH '$.Value',\n                          Dat VARCHAR2(100) PATH '$.Date',\n                          Service VARCHAR2(100) PATH '$.Service',\n                          Amount number PATH '$.Amount',\n                          IpAddress VARCHAR2(100) PATH '$.IpAddress'\n                          )\n                          )a\n\n\nwhere id=:id"

# ASANFinance/AsanDmInpl.dfm:812 VoenSet (TOracleDataSet)
SQL_ASAN_VOENSET = "select s.id,  json_value(info, '$.Response.PayerType.Type') AS payer_type,\n  json_value(info, '$.Response.PayerType.Description') AS payer_description,\n  nvl(json_value(info, '$.Response.NaturalPerson.LegalAddress'), json_value(info, '$.Response.LegalEntity.LegalAddress')) AS legal_address,\n  json_value(info, '$.Response.VOENInfo.VOEN') AS voen,\n  json_value(info, '$.Response.VOENInfo.CreateDate') AS voen_create_date,\n  json_value(info, '$.Response.Chief.Name') AS chief_name,\n  json_value(info, '$.Response.Chief.Surname') AS chief_surname,\n  json_value(info, '$.Response.Chief.Patronymic') AS chief_patronymic,\n  json_value(info, '$.Response.Chief.Name')||' '||\n  json_value(info, '$.Response.Chief.Surname')||' '||\n  json_value(info, '$.Response.Chief.Patronymic') AS full_name\n from asan_log s\n\nwhere s.id=:id"

# ASANFinance/AsanDmInpl.dfm:897 ods_link (TOracleDataSet)
SQL_ASAN_ODS_LINK = 'select*from asan_info'
